/* ================= THE ROUND: one composed daily session ================= */
let ROUND=null;
/* roundPlan() is the default selection: the same legs and minutes the Today hero, Today's plan and the builder show. */
function roundPlan(){return presetLegs(roundCatalog(),roundCap());}
function roundMinutes(){return roundPlan().reduce((s,g)=>s+g.min,0);}
function ui5Legs(){const legs=[];const due=dueKinds().length;
 if(due)legs.push({t:'due',label:'Review '+Math.min(due,4)+' due pattern'+(Math.min(due,4)>1?'s':''),min:5});
 const c=conceptOfDay();legs.push({t:'concept',label:'Concept of the day: '+c[1],min:2,c:c[0]});
 legs.push({t:'gym',label:'Five compensation sums',min:3});
 legs.push({t:'est',label:'Three estimates',min:3});
 legs.push({t:'steps',label:'Five step-by-step gases',min:8});
 const sc=SCENARIOS.find(x=>!(S.scen||{})[x.id])||SCENARIOS[dayNum()%SCENARIOS.length];legs.push({t:'scen',label:'Shift: '+sc.title,min:5,id:sc.id});
 legs.push({t:'teach',label:'Teach one idea back',min:3});
 return legs;}
function weakLeg(){const w=weakestStep();return w?{t:'weak',label:'Weakest step: '+STEPNAME[w.c]+' ('+Math.round(w.a*100)+'%)',min:5,c:w.c}:null;}
function roundCatalog(){const L0=ui5Legs(),wl=weakLeg(),o=[];if(wl)o.push(wl);L0.forEach(g=>{if(wl&&wl.c==='comp'&&g.t==='gym')return;o.push(g);});return o;}
const LEG_PRI=['weak','due','steps','gym','est','concept','scen','teach','five','case','noise','trend','hand'];
const UI5_QUICK_PRI=['weak','due','gym','est','concept','teach','steps','scen'];
function ui5Plan(){try{const p=typeof G!=='undefined'&&G.plan;return p&&p.status==='accepted'&&+p.minutes>0?+p.minutes:0;}catch(e){return 0;}}
function ui5SlotCap(){try{if(typeof slotFor==='function'&&typeof SLOT_MIN!=='undefined'){const c=SLOT_MIN[slotFor(today())];if(c!=null)return c;}}catch(e){}return 25;}
function roundCap(){const s=ui5SlotCap(),p=ui5Plan();return p?Math.min(p,s||p):s;}
function presetLegs(cat,cap,pri){if(!(cap>0))return [];pri=pri||LEG_PRI;const out=[];let t=0;[...cat].sort((a,b)=>pri.indexOf(a.t)-pri.indexOf(b.t)).forEach(g=>{if(t+g.min<=cap||!out.length){out.push(g);t+=g.min;}});return cat.filter(g=>out.includes(g));}
function startRound(){openRoundBuilder();}
function openRoundBuilder(){const cat=roundCatalog(),cap=roundCap(),key=g=>g.t+(g.id||''),opener=document.activeElement;
 const asKeys=a=>a.map(key).sort().join('|');
 const pre=[['quick','Quick 10',presetLegs(cat,10,UI5_QUICK_PRI)],['std','Standard 25',presetLegs(cat,25)],['all','Everything',cat.slice()]];
 if(asKeys(pre[2][2])===asKeys(pre[1][2]))pre.pop();
 let sel=new Set(presetLegs(cat,cap).map(key));const old=document.querySelector('.sheet-scrim');if(old)old.remove();
 const wl=cat.find(g=>g.t==='weak'),plan=ui5Plan(),slot=ui5SlotCap();
 const note=(wl?'Your weakest step comes first. ':'')+(plan?'Citrus planned '+plan+' min. ':'')+(cap<=0?'Today\'s shift leaves no time, so nothing is ticked: pick a leg if you want one. ':slot<25&&cap===slot?'Capped at '+cap+' min for today\'s shift. ':'');
 const sc=document.createElement('div');sc.className='sheet-scrim';
 sc.innerHTML='<div class="sheet" role="dialog" aria-modal="true" aria-labelledby="rbT" aria-describedby="rbNote"><div class="sheet-grab"></div><h2 id="rbT" tabindex="-1" style="font-size:1.1rem;margin:2px 0 0">Build today\'s Round</h2><p class="note" id="rbNote" style="margin:4px 0 10px">Tick the legs you want. '+esc(note)+'</p>'+
  '<div class="btnrow" style="margin-bottom:6px">'+pre.map(p=>'<button class="btn small" data-p="'+p[0]+'" aria-pressed="false">'+p[1]+'</button>').join('')+'</div>'+
  cat.map((g,i)=>'<label class="srow" style="cursor:pointer;min-height:44px"><div><b>'+esc(g.label)+'</b><span>about '+g.min+' min</span></div><input type="checkbox" data-i="'+i+'" style="width:22px;height:22px;accent-color:var(--accent);flex:none;margin:0 4px"></label>').join('')+
  '<div class="btnrow" style="position:sticky;bottom:-14px;background:var(--surface);padding:10px 0 4px;margin-top:6px;border-top:2px solid var(--line)"><button class="btn primary" id="rbBuild"></button><button class="btn" id="rbCancel">Cancel</button></div></div>';
 const sync=()=>{const tot=cat.filter(g=>sel.has(key(g))).reduce((s,g)=>s+g.min,0);sc.querySelectorAll('[data-i]').forEach(c=>{c.checked=sel.has(key(cat[+c.dataset.i]));});const b=sc.querySelector('#rbBuild');b.textContent='Start · '+tot+' min';b.disabled=!tot;const cur=[...sel].sort().join('|');sc.querySelectorAll('[data-p]').forEach(x=>{const p=pre.find(q=>q[0]===x.dataset.p);x.setAttribute('aria-pressed',String(asKeys(p[2])===cur));x.classList.toggle('primary',asKeys(p[2])===cur);});};
 sc.querySelectorAll('[data-i]').forEach(c=>c.onchange=()=>{const k=key(cat[+c.dataset.i]);c.checked?sel.add(k):sel.delete(k);sync();});
 sc.querySelectorAll('[data-p]').forEach(b=>b.onclick=()=>{sel=new Set(pre.find(q=>q[0]===b.dataset.p)[2].map(key));sync();});
 /* modal behaviour: inert background, focus trap, Escape and Back close it, focus returns to the opener */
 const bg=[...document.body.children].filter(x=>x!==sc&&!x.inert&&x.tagName!=='SCRIPT');let pushed=false,closing=null,done=false,mo=null;
 const finish=then=>{if(done)return;done=true;if(mo)mo.disconnect();document.removeEventListener('keydown',onKey,true);removeEventListener('popstate',onPop);bg.forEach(x=>{x.inert=false;});sc.classList.remove('on');setTimeout(()=>sc.remove(),200);
  if(then)then();else{const o=opener&&document.contains(opener)?opener:$('tRound');if(o&&o.focus)o.focus();}};
 let closing0=false;const close=then=>{if(done||closing0)return;if(pushed){closing=then||null;closing0=true;try{history.back();}catch(e){}setTimeout(()=>{if(!done)finish(then);},400);}else finish(then);};
 const onPop=()=>{if(done)return;finish(closing);};
 const onKey=e=>{if(done)return;if(e.key==='Escape'){e.preventDefault();e.stopPropagation();close();return;}
  if(e.key==='Tab'){const f=[...sc.querySelectorAll('button:not([disabled]),input,[tabindex="0"]')].filter(x=>x.offsetParent!==null);if(!f.length)return;const a=f[0],z=f[f.length-1];
   if(e.shiftKey&&(document.activeElement===a||!sc.contains(document.activeElement))){e.preventDefault();z.focus();}else if(!e.shiftKey&&(document.activeElement===z||!sc.contains(document.activeElement))){e.preventDefault();a.focus();}}};
 sc.querySelector('#rbCancel').onclick=()=>close();
 sc.querySelector('#rbBuild').onclick=()=>{const legs=cat.filter(g=>sel.has(key(g))).map(g=>Object.assign({},g));if(!legs.length)return;close(()=>{ROUND={legs,i:0,t0:Date.now(),xp0:S.xp||0,day:today()};S.round=ROUND;save();roundGo();});};
 sc.addEventListener('click',e=>{if(e.target===sc)close();});document.body.appendChild(sc);sync();
 bg.forEach(x=>{x.inert=true;});document.addEventListener('keydown',onKey,true);
 /* if anything else removes the sheet (another sheet, a route change), the background must not stay inert (T27-3) */
 try{mo=new MutationObserver(()=>{if(!document.body.contains(sc))finish(()=>{});});mo.observe(document.body,{childList:true});}catch(e){}
 try{history.pushState({sheet:1},'',location.href);pushed=true;addEventListener('popstate',onPop);}catch(e){}
 requestAnimationFrame(()=>{sc.classList.add('on');const h=$('rbT');if(h)h.focus();});}
/* view in which each kind of leg runs */
const UI5_LEGVIEW={due:'session',weak:'session',gym:'session',steps:'session',concept:'web',est:'est',scen:'scen',teach:'teach'};
function roundGo(){if(!ROUND)return;const g=ROUND.legs[ROUND.i];if(!g){roundFinish();return;}
 /* a leg that is already running is resumed, never restarted */
 const live=g.started&&({session:typeof SS!=='undefined'&&SS&&SS.round&&!SS.done,est:!!ES,scen:!!(SC&&SC.sc.id===g.id),teach:!!TB,web:true})[UI5_LEGVIEW[g.t]];
 if(live){if(g.t==='concept')WEBSEL=g.c;go(UI5_LEGVIEW[g.t]);renderRoundBar();return;}
 g.started=1;S.round=ROUND;
 switch(g.t){case 'due':startSession('due',{round:true,n:Math.min(4,Math.max(1,dueKinds().length))});break;
  case 'concept':WEBSEL=g.c;go('web');break;
  case 'weak':if(g.c==='comp')startSession('gym',{round:true,n:5});else startSession('steps',{round:true,n:4});break;
  case 'gym':startSession('gym',{round:true,n:5});break;
  case 'est':ES=null;ES_N=0;go('est');break;
  case 'steps':startSession('steps',{round:true,n:5});break;
  case 'scen':openScenario(g.id);break;
  case 'teach':TB=null;TB_PICK=null;go('teach');break;}
 renderRoundBar();}
function roundLegDone(skipped){if(!ROUND)return;const g=ROUND.legs[ROUND.i];if(g){if(skipped===true)g.skipped=1;else delete g.skipped;}ROUND.i++;S.round=ROUND;save();if(ROUND.i>=ROUND.legs.length){roundFinish();return;}toast('Next: '+ROUND.legs[ROUND.i].label);setTimeout(roundGo,300);}
function roundFinish(){const mins=Math.max(1,Math.round((Date.now()-ROUND.t0)/60000)),xp=(S.xp||0)-ROUND.xp0;const n=ROUND.legs.length,did=ROUND.legs.filter(g=>!g.skipped).length;
 ROUND=null;S.round=null;
 /* a Round counts only when at least half its legs were actually done */
 if(!did||did*2<n){save();renderRoundBar();go('today');setTimeout(()=>toast(did?'Round ended. Only '+did+' of '+n+' legs were done, so it does not count as today\'s Round.':'Round ended. Nothing was finished, so today is still open.'),200);return;}
 S.roundsDone=(S.roundsDone||0)+1;S.lastRound=today();S.lastRoundMin=Math.min(1440,mins);addXP(40);touchDay();ui5Badges();save();renderRoundBar();confetti();go('today');setTimeout(()=>toast('Round complete · '+did+' of '+n+' legs · '+mins+' min'+(S.quiet===false?' · +'+(xp+40)+' XP':''),'good'),200);}
function stopRound(){ROUND=null;S.round=null;save();renderRoundBar();toast('Round stopped. Progress so far is kept.');}
let UI5_BAROBS=null;
function ui5BarSync(){const b=$('rbGo');if(!b||!ROUND)return;const g=ROUND.legs[ROUND.i];b.hidden=!g||VIEW===UI5_LEGVIEW[g.t]&&!!g.started;}
function renderRoundBar(){let bar=$('roundbar');document.body.classList.toggle('inround',!!ROUND);if(!ROUND){if(bar)bar.remove();return;}
 if(!bar){bar=document.createElement('div');bar.id='roundbar';document.body.appendChild(bar);}
 const g=ROUND.legs[ROUND.i];bar.innerHTML='<div class="rb-in"><span class="eyebrow">Round · leg '+(ROUND.i+1)+'/'+ROUND.legs.length+'</span><div class="pips" role="img" aria-label="Leg '+(ROUND.i+1)+' of '+ROUND.legs.length+'">'+ROUND.legs.map((x,i)=>'<i class="'+(i<ROUND.i?(x.skipped?'':'ok'):i===ROUND.i?'cur':'')+'"></i>').join('')+'</div><b>'+esc(g?g.label:'')+'</b><button class="btn small" id="rbGo">'+(g&&g.started?'Back to this leg':'Go')+'</button><button class="btn small" id="rbSkip">Skip leg</button><button class="btn small" id="rbStop" aria-label="Stop the Round">✕</button></div>';
 $('rbGo').onclick=roundGo;$('rbSkip').onclick=()=>{if(typeof SS!=='undefined'&&SS&&!SS.done){clearInterval(SS.timer);clearInterval(SS.clock);SS.done=true;}roundLegDone(true);};$('rbStop').onclick=()=>{stopRound();if(VIEW==='today')RENDER.today();};
 ui5BarSync();
 if(!UI5_BAROBS&&typeof MutationObserver!=='undefined'){UI5_BAROBS=new MutationObserver(ui5BarSync);document.querySelectorAll('section.view').forEach(s=>UI5_BAROBS.observe(s,{attributes:true,attributeFilter:['hidden']}));}}
const legBtn=t=>ROUND&&ROUND.legs[ROUND.i]&&ROUND.legs[ROUND.i].t===t?'<button class="btn primary" data-leg="1">Next leg →</button>':'';
document.addEventListener('click',e=>{if(e.target.closest('[data-leg]')){e.preventDefault();roundLegDone();}});

