/* a shift in progress survives a reload on this device */
function ui5ScenKeep(x){try{if(x)localStorage.setItem('buffer.scenRun',JSON.stringify({id:x.sc.id,i:x.i,wrong:x.wrong,tried:x.tried,log:x.log}));else localStorage.removeItem('buffer.scenRun');}catch(e){}}
function ui5ScenRun(){try{const r=JSON.parse(localStorage.getItem('buffer.scenRun')||'null');const sc=r&&SCENARIOS.find(x=>x.id===r.id);return sc&&r.i<sc.steps.length?Object.assign(r,{sc}):null;}catch(e){return null;}}
function openScenario(id,resume){const sc=SCENARIOS.find(x=>x.id===id)||SCENARIOS[0];const r=resume?ui5ScenRun():null;
 SC=r&&r.id===sc.id?{sc,i:r.i,wrong:r.wrong||0,tried:r.tried||{},log:r.log||[]}:{sc,i:0,wrong:0,tried:{},log:[]};ui5ScenKeep(SC);go('scen',true);setHash('scen-'+sc.id);}
RENDER.scen=function(){const el=$('v-scen');
 if(!SC){el.innerHTML=UI5_CRUMB+'<div class="view-head"><div class="ph"><span class="eyebrow">'+SCENARIOS.length+' shifts · '+Object.keys(S.scen||{}).length+' done</span><h1>Shifts</h1><p>Branching scenarios set where you work. Pick an option; a wrong turn shows what happens, then you choose again.</p></div></div><div class="tiles">'+SCENARIOS.map(sc=>{const r=(S.scen||{})[sc.id],run=ui5ScenRun(),cur=run&&run.id===sc.id&&run.i>0;const tile='<button class="tile'+(r?' on':'')+'" data-sc="'+sc.id+'"'+(r?' style="flex:1;padding-right:56px"':'')+'><span class="mono-mark">'+ic('scen')+'</span><span><small class="meta">'+(cur?'Resume (decision '+(run.i+1)+'/'+sc.steps.length+') · ':'')+esc(sc.where)+(r?' · best: '+(r.wrong?r.wrong+' wrong turn'+(r.wrong>1?'s':''):'clean run'):'')+'</small><b>'+esc(sc.title)+'</b><span class="d">'+esc(sc.intro)+'</span></span></button>';
  /* a finished shift has a second action (Forget my result) in the hold menu: a visible ⋯ opens the same menu (T27-11) */
  return r?'<div style="position:relative;display:flex;min-width:0">'+tile+'<button type="button" class="iconbtn kitmore" data-kitmore="#v-scen .tile[data-sc=&quot;'+sc.id+'&quot;]" aria-label="More actions for '+esc(sc.title)+'" aria-haspopup="dialog" style="position:absolute;top:6px;right:6px">⋯</button></div>':tile;}).join('')+'</div>';
  el.querySelectorAll('[data-sc]').forEach(b=>b.onclick=()=>openScenario(b.dataset.sc,true));return;}
 const sc=SC.sc,st=sc.steps[SC.i];
 if(!st){/* award and save once per run; keep the best run (fewest wrong turns) */
  if(!SC.saved){SC.saved=true;S.scen=S.scen||{};const prev=S.scen[sc.id];SC.first=!prev;S.scen[sc.id]=prev&&prev.wrong<SC.wrong?Object.assign({},prev,{last:ddmmyyyy()}):{wrong:SC.wrong,d:ddmmyyyy(),last:ddmmyyyy()};addXP(Math.max(10,30-5*SC.wrong));touchDay();ui5Badges();save();ui5ScenKeep(null);}
  const first=SC.first&&!SC.conf;SC.conf=true;
  el.innerHTML='<div class="crumbs"><button id="scBack">← Shifts</button><span class="eyebrow">'+esc(sc.where)+'</span></div><div class="card raised" style="display:flex;flex-direction:column;gap:12px"><span class="eyebrow">Shift complete</span><h1>'+esc(sc.title)+'</h1><p>'+(SC.wrong?SC.wrong+' wrong turn'+(SC.wrong>1?'s':'')+'. Each was a real-world trap; run it again in a few days.':'Clean run: every call right first time.')+(S.quiet===false?' +'+Math.max(10,30-5*SC.wrong)+' XP.':'')+'</p><div class="scn-log">'+SC.log.map(x=>'<div class="'+(x.ok?'good':'bad')+'"><b>'+esc(x.q)+'</b> '+esc(x.a)+'</div>').join('')+'</div><div class="btnrow">'+legBtn('scen')+'<button class="btn" id="scAgain">Run it again</button><button class="btn" id="scAll">All shifts</button></div></div>';
  $('scBack').onclick=()=>{SC=null;RENDER.scen();};$('scAgain').onclick=()=>openScenario(sc.id);$('scAll').onclick=()=>{SC=null;RENDER.scen();};if(first)confetti();return;}
 const tried=SC.tried[SC.i]||{};const solved=Object.keys(tried).some(k=>st.o[k][1]);
 el.innerHTML='<div class="crumbs"><button id="scBack">← Shifts</button><span class="eyebrow">'+esc(sc.where)+'</span><span class="eyebrow" style="margin-left:auto;color:var(--muted)">Decision '+(SC.i+1)+' / '+sc.steps.length+'</span></div><div class="pips">'+sc.steps.map((_,i)=>'<i class="'+(i<SC.i?'ok':i===SC.i?'cur':'')+'"></i>').join('')+'</div>'+
 (SC.i===0?'<div class="card tint"><h2>'+esc(sc.title)+'</h2><p class="vig" style="margin-top:6px">'+esc(sc.intro)+'</p></div>':'')+
 '<div class="'+(st.gas?'dgrid':'')+'">'+(st.gas?'<div class="card stick">'+slip(Object.assign({},st.gas,{hco3:st.gas.hco3}),{lv:4,urea:!!st.gas.osm})+'</div>':'')+'<div class="card scn-step"><p class="p">'+esc(st.p)+'</p><p class="ask">'+esc(st.q)+'</p><div class="scn-opts">'+scOrd().map((i,k)=>{const o=st.o[i],t=tried[i];return '<button class="opt'+(t?(o[1]?' right':' wrong'):'')+'" data-o="'+i+'"'+(t||solved?' disabled':'')+'><kbd>'+(k+1)+'</kbd><span>'+esc(o[0])+'</span></button>';}).join('')+'</div>'+
  Object.keys(tried).map(k=>'<p class="why '+(st.o[k][1]?'ok':'no')+'"><b>'+(st.o[k][1]?'Right.':'What happens:')+'</b> '+esc(st.o[k][2])+'</p>').join('')+(solved?'<div class="btnrow"><button class="btn primary" id="scNext">'+(SC.i+1<sc.steps.length?'Next decision →':'Finish the shift →')+'</button></div>':'')+'</div></div>';
 $('scBack').onclick=()=>{SC=null;RENDER.scen();setHash('scen');};
 el.querySelectorAll('.opt[data-o]').forEach(b=>b.onclick=()=>scAnswer(+b.dataset.o));
 if($('scNext'))$('scNext').onclick=()=>{SC.i++;if(SC.i<sc.steps.length)ui5ScenKeep(SC);RENDER.scen();window.scrollTo(0,0);};};
function scOrd(){SC.ord=SC.ord||{};return SC.ord[SC.i]=SC.ord[SC.i]||shuffle(SC.sc.steps[SC.i].o.map((_,i)=>i));}
function srOrd(){SR.ord=SR.ord||{};return SR.ord[SR.i]=SR.ord[SR.i]||shuffle(SR.s.pts[SR.i].opts.map((_,i)=>i));}
function scAnswer(i){if(VIEW!=='scen'||!SC)return;const st=SC.sc.steps[SC.i];if(!st||!st.o[i])return;const tried=SC.tried[SC.i]=SC.tried[SC.i]||{};if(tried[i]||Object.keys(tried).some(k=>st.o[k][1]))return;tried[i]=1;
 if(st.o[i][1]){SC.log.push({q:st.q,a:st.o[i][0],ok:Object.keys(tried).length===1});addXP(3);}else SC.wrong++;ui5ScenKeep(SC);RENDER.scen();}

