 const ui5Sg=x=>(x<0?'− ':'+ ')+Math.abs(x).toFixed(1);
 if(k==='ph'){const h=Math.round(rnd(6,40)),p=Math.round(rnd(18,85));const a=phFrom(h,p);if(a<6.9||a>7.7)return estNew();q={k,text:'HCO₃⁻ <b>'+h+'</b> mmol/L, PCO₂ <b>'+P(p)+' '+PU()+'</b>.',ask:'Estimate the pH',unit:'',min:6.9,max:7.7,step:0.01,tol:0.04,ans:a,fmt:x=>x.toFixed(2),work:(kp?'Ratio '+h+' ÷ (0.225 × '+P(p)+') = '+(h/(0.03*p)).toFixed(1)+' (normal 20). pH = 6.1 + log('+(h/(0.03*p)).toFixed(1)+') = '+a.toFixed(2)+'. Henderson check: [H⁺] = 180 × '+P(p)+' ÷ '+h+' = '+Math.round(24*p/h)+' nmol/L.':'Ratio '+h+' ÷ (0.03 × '+p+') = '+(h/(0.03*p)).toFixed(1)+' (normal 20). pH = 6.1 + log('+(h/(0.03*p)).toFixed(1)+') = '+a.toFixed(2)+'. Henderson check: [H⁺] = 24 × '+p+' ÷ '+h+' = '+Math.round(24*p/h)+' nmol/L.')};}
 else if(k==='winters'){const h=Math.round(rnd(5,21));const a=1.5*h+8;const sc=h>=10&&h<=18?' Shortcut: HCO₃⁻ + 15 = '+(h+15)+' mmHg (fine for HCO₃⁻ 10–18).':'';
  q=kp?{k,text:'Metabolic acidosis with HCO₃⁻ <b>'+h+'</b> mmol/L.',ask:'Estimate the expected PCO₂ (kPa)',unit:' kPa',min:1.3,max:6.7,step:0.1,tol:0.4,ans:a/KPA,fmt:x=>x.toFixed(1),work:'Winter\'s (in mmHg): 1.5 × '+h+' + 8 = '+r1(a)+' ± 2 mmHg = '+(a/KPA).toFixed(1)+' ± 0.3 kPa.'+sc}
   :{k,text:'Metabolic acidosis with HCO₃⁻ <b>'+h+'</b> mmol/L.',ask:'Estimate the expected PCO₂ (mmHg)',unit:' mmHg',min:10,max:50,step:1,tol:3,ans:a,fmt:x=>String(Math.round(x)),work:'Winter\'s: 1.5 × '+h+' + 8 = '+r1(a)+' ± 2.'+sc};}
 else if(k==='hplus'){const ph=r2(rnd(7.0,7.6));const a=Math.pow(10,9-ph);q={k,text:'pH <b>'+ph.toFixed(2)+'</b>.',ask:'Estimate [H⁺] (nmol/L)',unit:' nmol/L',min:20,max:110,step:1,tol:5,ans:a,fmt:x=>String(Math.round(x)),work:'10^(9 − '+ph.toFixed(2)+') = '+Math.round(a)+' nmol/L.'+(ph>=7.2&&ph<=7.5?' The 80 rule: 80 − '+Math.round((ph-7)*100)+' = '+(80-Math.round((ph-7)*100))+'.':' Outside 7.20–7.50 the 80 rule drifts; remember 7.10 ≈ 80, 7.00 ≈ 100.')};}
 else if(k==='agc'){const na=Math.round(rnd(132,146)),hc=Math.round(rnd(8,24)),cl=Math.round(na-hc-rnd(6,24)),alb=Math.round(rnd(18,42));const ag=na-cl-hc,a=ag+0.25*(40-alb);q={k,text:'Na <b>'+na+'</b>, Cl <b>'+cl+'</b>, HCO₃⁻ <b>'+hc+'</b>, albumin <b>'+alb+'</b> g/L.',ask:'Estimate the albumin-corrected anion gap',unit:'',min:0,max:40,step:1,tol:2,ans:a,fmt:x=>String(Math.round(x)),work:'AG = '+na+' − ('+cl+' + '+hc+') = '+ag+'. Correction 0.25 × (40 − '+alb+') = '+ui5Sg(0.25*(40-alb))+' → '+r1(a)+'.'};}
 else{const pc=Math.round(rnd(26,70)),age=Math.round(rnd(25,80)),pa=(S.patm||760);const PA=0.21*(pa-47)-pc/0.8;const po=Math.round(PA-rnd(2,45));if(po<45)return estNew();const a=PA-po,lim=age/4+4;
  if(kp){q={k,text:'Room air'+(pa!==760?' at '+P(pa)+' kPa':'')+': PaCO₂ <b>'+P(pc)+'</b> kPa, PaO₂ <b>'+P(po)+'</b> kPa, age <b>'+age+'</b>.',ask:'Estimate the A–a gradient (kPa)',unit:' kPa',min:0,max:8,step:0.1,tol:0.7,ans:a/KPA,fmt:x=>x.toFixed(1),work:'PAO₂ = 0.21 × ('+P(pa)+' − 6.3) − '+P(pc)+' ÷ 0.8 = '+P(PA)+' kPa. A–a = '+P(PA)+' − '+P(po)+' = '+(a/KPA).toFixed(1)+' kPa. Expected ≤ age/4 + 4 = '+Math.round(lim)+' mmHg ('+(lim/KPA).toFixed(1)+' kPa) for age '+age+': '+(a>lim?'raised.':'normal.')};ES={q,v:null,shown:false};return;}q={k,text:'Room air'+(pa!==760?' at '+pa+' mmHg':'')+': PaCO₂ <b>'+pc+'</b>, PaO₂ <b>'+po+'</b>, age <b>'+age+'</b>.',ask:'Estimate the A–a gradient (mmHg)',unit:' mmHg',min:0,max:60,step:1,tol:5,ans:a,fmt:x=>String(Math.round(x)),work:'PAO₂ = 0.21 × ('+pa+' − 47) − '+pc+' ÷ 0.8 = '+Math.round(PA)+'. A–a = '+Math.round(PA)+' − '+po+' = '+Math.round(a)+'. Expected ≤ age/4 + 4 = '+Math.round(lim)+' for age '+age+': '+(a>lim?'raised.':'normal.')};}
