/* displayed (rounded) values, so "off by" and "close" match what is on screen */
function ui5EstDiff(q,v){return Math.abs(+q.fmt(v)-+q.fmt(q.ans));}
RENDER.est=function(){const el=$('v-est');if(!ES)estNew();const q=ES.q;
 /* the thumb starts at a random point and must be moved before locking, so an untouched slider cannot score */
 if(ES.v0==null){const n=Math.round((q.max-q.min)/q.step);ES.v0=+(q.min+Math.round(Math.random()*n)*q.step).toFixed(2);}
 const v=ES.v==null?ES.v0:ES.v;S.est=S.est||{n:0,c:0};
 const pct=x=>Math.max(0,Math.min(100,(x-q.min)/(q.max-q.min)*100));
 el.innerHTML=UI5_CRUMB+'<div class="view-head"><div class="ph"><span class="eyebrow">Gas sense · '+S.est.n+' done · '+(S.est.n?Math.round(S.est.c/S.est.n*100):0)+'% close</span><h1>Estimate first</h1><p>Guess on the slider, then see the working. Number sense catches calculation slips at the bedside.</p></div></div>'+
 '<div class="card" style="display:flex;flex-direction:column;gap:14px"><p class="headline">'+q.text+'</p><p class="ask">'+q.ask+'</p><div class="ctrl"><label for="esIn"><span>Your guess</span><output id="esOut">'+q.fmt(v)+q.unit+'</output></label><input type="range" id="esIn" min="'+q.min+'" max="'+q.max+'" step="'+q.step+'" value="'+v+'"'+(ES.shown?' disabled':'')+'></div>'+
 /* the track (guess against answer and band) shows only once the guess is locked; before that the slider is the only control (T18-40) */
 (ES.shown?'<div><div class="est-track"><span class="est-band" style="left:'+pct(q.ans-q.tol)+'%;width:'+(pct(q.ans+q.tol)-pct(q.ans-q.tol))+'%"></span><i class="est-you" style="left:'+pct(v)+'%"></i><i class="est-ans" style="left:'+pct(q.ans)+'%"></i></div><div class="est-lab"><span>'+q.fmt(q.min)+'</span><span>'+q.fmt(q.max)+'</span></div></div>':'')+
 (ES.shown?'<div class="fb '+(ES.close?'ok':'no')+'"><div class="verdict"><i>'+(ES.close?'✓':'✗')+'</i>'+(ES.close?'Close enough.':'Off by '+q.fmt(ui5EstDiff(q,v))+'.')+' Answer: '+q.fmt(q.ans)+q.unit+'</div><p>'+q.work+'</p><p class="note">Close means within ± '+q.fmt(q.tol)+q.unit+' for this kind of estimate.</p></div><div class="btnrow">'+(ROUND&&ROUND.legs[ROUND.i]&&ROUND.legs[ROUND.i].t==='est'&&ES_N>=3?legBtn('est'):'<button class="btn primary" id="esNext">Next →</button>')+'</div>':'<div class="btnrow"><button class="btn primary" id="esLock"'+(ES.v==null?' disabled':'')+'>Lock it in</button><span class="note" id="esTol">'+(ES.v==null?'Move the slider to your guess. ':'')+'Within ± '+q.fmt(q.tol)+q.unit+' counts as close.</span></div>')+'</div>';
 const inp=$('esIn');if(inp&&!ES.shown)inp.oninput=e=>{ES.v=+e.target.value;$('esOut').textContent=q.fmt(ES.v)+q.unit;const yu=el.querySelector('.est-you');if(yu)yu.style.left=pct(ES.v)+'%';const b=$('esLock');if(b&&b.disabled){b.disabled=false;$('esTol').textContent='Within ± '+q.fmt(q.tol)+q.unit+' counts as close.';}};
 if($('esLock'))$('esLock').onclick=()=>{if(ES.v==null)return;const g=ES.v;ES.shown=true;ES.close=ui5EstDiff(q,g)<=q.tol+1e-9;S.est.n++;ES_N++;if(ES.close){S.est.c++;addXP(6);}touchDay();ui5Badges();save();RENDER.est();};
 if($('esNext'))$('esNext').onclick=()=>{estNew();RENDER.est();};};

