/* lessons marked noflash (app meta) stay out; a card with the same answer and a similar prompt as an earlier one is dropped */
function ui5FlashDup(seen,f,b){const nb=String(b).toLowerCase().replace(/[^a-z0-9.+<>=≥≤−-]/g,''),w=s=>String(s).toLowerCase().split(/[^a-z0-9₂]+/).filter(x=>x.length>=2);const fw=w(f);const hit=(seen[nb]||[]).some(g=>w(g).some(x=>fw.includes(x)));(seen[nb]=seen[nb]||[]).push(f);return hit;}
const FLASH=(()=>{const out=[],seen={};L.filter(l=>!l.noflash).forEach(l=>(l.keys||[]).forEach((k,i)=>{if(!ui5FlashDup(seen,k[0],k[1]))out.push({id:l.id+'-'+i,f:k[0],b:k[1],src:l.t,l:l.id});}));
 [['Winter\'s formula','PCO₂ = 1.5 × HCO₃⁻ + 8 ± 2'],['Metabolic alkalosis compensation','PCO₂ = 0.7 × HCO₃⁻ + 20 ± 5'],['Respiratory acidosis: HCO₃⁻ per 10 mmHg','+1 acute · +4 chronic'],['Respiratory alkalosis: HCO₃⁻ per 10 mmHg','−2 acute · −5 chronic'],['Anion gap','Na − (Cl + HCO₃⁻)'],['Δ ratio','(AG − 12) ÷ (24 − HCO₃⁻)'],['Alveolar gas equation','PAO₂ = FiO₂ × (P_atm − 47) − PaCO₂ ÷ 0.8'],['Osmolar gap','measured − (2Na + glucose + urea)']].forEach((x,i)=>out.push({id:'rule-'+i,f:x[0],b:x[1],src:'Core rules',l:'comp'}));return out;})();
let FL=null;
function flashDeck(){const now=Date.now();S.flash=S.flash||{};const due=FLASH.filter(c=>S.flash[c.id]&&S.flash[c.id].due<=now);const fresh=FLASH.filter(c=>!S.flash[c.id]);return shuffle(due).concat(shuffle(fresh)).slice(0,20);}
let UI5_FLKEEP=false;
RENDER.flash=function(){const el=$('v-flash');const keep=UI5_FLKEEP;UI5_FLKEEP=false;
 /* coming back to a finished deck starts a fresh one (or shows what is due) instead of the old result */
 if(FL&&FL.done&&!keep)FL={deck:flashDeck(),i:0,flipped:false,got:0,done:false,swipes:FL.swipes||0};
 if(!FL||FL.i>=FL.deck.length&&!FL.done){FL={deck:flashDeck(),i:0,flipped:false,got:0,done:false,swipes:FL?FL.swipes:0};}
 const c=FL.deck[FL.i];
 if(!c){el.innerHTML=UI5_CRUMB+'<div class="view-head"><div class="ph"><span class="eyebrow">Number flash</span><h1>'+(FL.deck.length?'Deck done':'Nothing due')+'</h1></div></div><div class="card" style="display:flex;flex-direction:column;gap:10px"><p>'+(FL.deck.length?FL.got+' of '+FL.deck.length+' known.':'All '+FLASH.length+' cards are scheduled for later.')+' Cards you knew come back after 3, 7, 16 and 35 days; misses come back tomorrow.'+(()=>{const n=FLASH.filter(x=>S.flash[x.id]&&S.flash[x.id].due<=Date.now()).length;return n?' '+n+' card'+(n>1?'s are':' is')+' due now.':'';})()+'</p><div class="btnrow"><button class="btn primary" id="flAgain">Another deck</button><button class="btn" data-go="practice">Practice</button></div></div>';$('flAgain').onclick=()=>{FL=null;RENDER.flash();};return;}
 const known=Object.values(S.flash||{}).filter(x=>x.box>=2).length;
 el.innerHTML=UI5_CRUMB+'<div class="view-head"><div class="ph"><span class="eyebrow">Number flash · '+(FL.i+1)+'/'+FL.deck.length+' · '+known+' of '+FLASH.length+' known</span><h1>Recall the number</h1></div></div><div role="progressbar" aria-label="Deck progress" aria-valuemin="0" aria-valuemax="'+FL.deck.length+'" aria-valuenow="'+FL.i+'" style="height:6px;background:var(--surface-2);border:1px solid var(--line);margin-bottom:12px"><i style="display:block;height:100%;width:'+Math.round(FL.i/FL.deck.length*100)+'%;background:var(--accent)"></i></div><div class="flashwrap"><div class="flashcard" id="flCard" tabindex="0" role="button" aria-label="Flash card, tap to flip"><small>'+esc(c.src)+'</small><div class="fq">'+esc(c.f+(S.units==='kPa'&&/per 10 mmHg/.test(c.f)?' (per 1.3 kPa)':''))+'</div>'+(FL.flipped?'<div class="fa">'+esc(c.b)+'</div>':'<small>Tap to show</small>')+'</div>'+(FL.flipped?'<div class="btnrow"><button class="btn" id="flNo">← Again</button><button class="btn primary" id="flYes">Got it →</button></div>':'<div class="btnrow"><button class="btn primary" id="flFlip">Show</button></div>')+((FL.swipes||0)<5?'<p class="note">Swipe the card: right if you knew it, left if not. Arrow keys work too.</p>':'')+'</div>';
 if(FL.flipped&&!FL.flipT)FL.flipT=Date.now();
 const flip=()=>{FL.flipped=true;FL.flipT=Date.now();RENDER.flash();};$('flCard').onclick=()=>{if(!FL.flipped)flip();};if($('flFlip'))$('flFlip').onclick=flip;
 if($('flYes'))$('flYes').onclick=()=>flashRate(true);if($('flNo'))$('flNo').onclick=()=>flashRate(false);};
/* a card is only marked after its answer has been on screen: a swipe on an unflipped card just flips it */
function flashRate(ok){if(!FL)return;const c=FL.deck[FL.i];if(!c)return;if(!FL.flipped){FL.flipped=true;FL.flipT=Date.now();RENDER.flash();return;}if(Date.now()-(FL.flipT||0)<450)return;FL.flipT=0;const s=S.flash[c.id]||{box:0};s.box=ok?Math.min(4,(s.box||0)+1):0;s.due=Date.now()+[1,3,7,16,35][s.box]*864e5;S.flash[c.id]=s;if(ok){FL.got++;addXP(1);}touchDay();ui5Badges();save();FL.i++;FL.flipped=false;if(FL.i>=FL.deck.length)FL.done=true;UI5_FLKEEP=true;RENDER.flash();}
